import 'dart:io';

import 'package:serverpod/protocol.dart' show ColumnType, TableDefinition;
import 'package:test/test.dart';
import 'package:wonky_revlog/schema.dart';
import 'package:wonky_server/src/generated/protocol.dart';
import 'package:wonky_sheets_core/revlog.dart' show sheetsSchema;
import 'package:wonky_slides_core/revlog.dart' show slidesSchema;

/// RevLog schema guard (RevLog spec 17 part 2 §4.1): `sheetsSchema` and
/// `slidesSchema` (generated by `tool/gen_rev_schema.dart`) must describe the
/// generated server tables exactly. A model change without regenerating the
/// schema fails here: rerun `dart run tool/gen_rev_schema.dart` in the
/// repository root.
void main() {
  final tables = {
    for (final t in Protocol.targetTableDefinitions) t.name: t,
  };
  final enums = _serverEnums();

  for (final schema in [sheetsSchema, slidesSchema]) {
    group('Given the ${schema.app} RevLog schema', () {
      test('when compared with the server then every table exists there', () {
        expect(
          [
            for (final t in schema.tables)
              if (!tables.containsKey(t.name)) t.name,
          ],
          isEmpty,
        );
      });

      for (final rt in schema.tables) {
        final st = tables[rt.name];
        if (st == null) continue;
        group('and its table ${rt.name}', () {
          test('when compared with the server columns then names, types and '
              'nullability match, plus fileId and revision', () {
            final server = {
              for (final c in st.columns)
                if (c.name != 'id') c.name: c,
            };
            expect(server.keys.toSet(), {
              ...rt.columnNames,
              'fileId',
              'revision',
            });
            for (final c in rt.columns) {
              final sc = server[c.name]!;
              expect(
                (sc.columnType, sc.isNullable),
                (_columnType(c.type), c.nullable),
                reason: '${rt.name}.${c.name}',
              );
            }
          });

          test('when compared with the server foreign keys then the parents '
              'match', () {
            final fks = {
              for (final fk in st.foreignKeys)
                if (fk.referenceTable != 'rev_file')
                  fk.columns.single: fk.referenceTable,
            };
            final parents = {
              for (final p in rt.parents)
                // Cell keys are cascade parents without a foreign key
                // (RevLog spec 02 §2.1).
                if (!(rt.name == 'cell' &&
                    (p.column == 'rowId' || p.column == 'columnId')))
                  p.column: p.table,
            };
            expect(fks, parents);
          });

          test('when compared with the server enums then the value names '
              'match', () {
            for (final c in rt.columns) {
              if (c.type != RevColumnType.enumName) continue;
              final dartType = st.columns
                  .firstWhere((s) => s.name == c.name)
                  .dartType!
                  .split(':')
                  .last
                  .replaceAll('?', '');
              expect(
                c.enumValues,
                enums[dartType],
                reason: '${rt.name}.${c.name} ($dartType)',
              );
            }
          });
        });
      }
    });
  }

  test('when a server table is versioned by RevLog then it is in one of the '
      'schemas', () {
    final described = {
      for (final s in [sheetsSchema, slidesSchema])
        for (final t in s.tables) t.name,
    };
    final versioned = [
      for (final TableDefinition t in tables.values)
        if (t.foreignKeys.any(
              (fk) =>
                  fk.referenceTable == 'rev_file' &&
                  fk.columns.single == 'fileId',
            ) &&
            t.columns.any((c) => c.name == 'revision') &&
            t.name != 'rev_op')
          t.name,
    ];
    expect(versioned.where((t) => !described.contains(t)), isEmpty);
  });
}

ColumnType _columnType(RevColumnType t) => switch (t) {
  RevColumnType.uuid => ColumnType.uuid,
  RevColumnType.string ||
  RevColumnType.enumName ||
  RevColumnType.json => ColumnType.text,
  RevColumnType.int => ColumnType.bigint,
  RevColumnType.double => ColumnType.doublePrecision,
  RevColumnType.bool => ColumnType.boolean,
  RevColumnType.dateTime => ColumnType.timestampWithoutTimeZone,
};

/// The enums of the server models (`enum:` in `.spy.yaml`), by name.
Map<String, List<String>> _serverEnums() {
  final out = <String, List<String>>{};
  for (final f in Directory('lib/src').listSync(recursive: true)) {
    if (f is! File || !f.path.endsWith('.spy.yaml')) continue;
    String? name;
    final values = <String>[];
    var inValues = false;
    for (final raw in f.readAsLinesSync()) {
      final line = raw.replaceAll('\r', '');
      if (line.startsWith('enum:')) name = line.substring(5).trim();
      if (line.startsWith('values:')) {
        inValues = true;
        continue;
      }
      if (inValues) {
        final m = RegExp(r'^\s+-\s*(\w+)').firstMatch(line);
        if (m != null) {
          values.add(m.group(1)!);
        } else if (line.isNotEmpty && !line.startsWith(' ')) {
          inValues = false;
        }
      }
    }
    if (name != null) out[name] = values;
  }
  return out;
}
